-- Flyway baseline (Phase 9.2) — the full schema as generated by Hibernate.
-- On an existing database, set spring.flyway.baseline-on-migrate=true so this is marked
-- applied without running. On a fresh database, Flyway runs this to create the schema.
-- After enabling Flyway, set spring.jpa.hibernate.ddl-auto=validate (or none).

create table audit_log (created_at timestamp, id integer, role varchar(12) check (role in ('ADMIN','HR','EMPLOYEE')), action varchar(24) not null, entity varchar(40) not null, entity_id varchar(60), username varchar(60) not null, summary varchar(240), primary key (id));
create table contribution_brackets (amount float not null, lower_bound float not null, rate float not null, seq integer not null, upper_bound float not null, id integer, table_id bigint not null, primary key (id));
create table contribution_tables (active boolean not null, effective_from date not null, created_at timestamp, id integer, agency varchar(12) not null check (agency in ('SSS','PHILHEALTH','PAGIBIG','BIR')), note varchar(120), primary key (id));
create table employees (active boolean not null, hourly_rate float not null, monthly_rate float not null, created_at timestamp, type varchar(20) not null check (type in ('REGULAR','PROBATIONARY','CONTRACTUAL','PART_TIMER')), id varchar(40) not null, bank_account varchar(60), full_name varchar(120) not null, primary key (id));
create table holidays (date date not null unique, id integer, type varchar(24) not null check (type in ('NONE','REGULAR_HOLIDAY','SPECIAL_OR_REST_DAY')), name varchar(120) not null, primary key (id));
create table leave_balances (credits integer not null, used integer not null, year integer not null, id integer, leave_type_id bigint not null, employee_id varchar(40) not null, primary key (id));
create table leave_requests (days integer not null, end_date date not null, start_date date not null, created_at timestamp, id integer, leave_type_id bigint not null, status varchar(12) not null check (status in ('PENDING','APPROVED','REJECTED')), employee_id varchar(40) not null, decided_by varchar(60), reason varchar(240), primary key (id));
create table leave_types (default_annual_credits integer not null, paid boolean not null, id integer, name varchar(60) not null unique, primary key (id));
create table loan_payments (amount float not null, created_at timestamp, id integer, loan_id bigint not null, payslip_id bigint, period varchar(20) not null, primary key (id));
create table loans (balance float not null, per_cutoff_amount float not null, principal float not null, created_at timestamp, id integer, status varchar(12) not null check (status in ('ACTIVE','PAID','CANCELLED')), type varchar(20) not null check (type in ('SSS','PAGIBIG','COMPANY','CASH_ADVANCE')), employee_id varchar(40) not null, start_period varchar(40), primary key (id));
create table pay_items (active boolean not null, amount float not null, recurring boolean not null, taxable boolean not null, created_at timestamp, id integer, kind varchar(12) not null check (kind in ('ALLOWANCE','DEDUCTION')), employee_id varchar(40) not null, name varchar(60) not null, primary key (id));
create table payroll_runs (employee_count integer not null, total_deductions float not null, total_gross float not null, total_net float not null, created_at timestamp, id integer, cutoff_period varchar(20) not null, status varchar(20) not null check (status in ('DRAFT','APPROVED','LOCKED')), primary key (id));
create table payroll_settings (id integer not null, leave_contractual integer not null, leave_part_timer integer not null, leave_probationary integer not null, leave_regular integer not null, lunch_start_hour float not null, overtime_start_hour float not null, workday_start_hour float not null, working_days integer not null, primary key (id));
create table payslips (absence_penalty float not null, absent_days integer not null, allowances float not null, basic_pay float not null, employer_ec float not null, employer_pagibig float not null, employer_philhealth float not null, employer_sss float not null, gross_pay float not null, loan float not null, net_pay float not null, night_diff_pay float not null, other_deductions float not null, overtime_hours float not null, overtime_pay float not null, pagibig float not null, philhealth float not null, sss float not null, tax float not null, total_hours float not null, undertime_hours float not null, undertime_penalty float not null, created_at timestamp, id integer, run_id bigint, cutoff_period varchar(20) not null, employee_type varchar(20) not null check (employee_type in ('REGULAR','PROBATIONARY','CONTRACTUAL','PART_TIMER')), employee_id varchar(40) not null, employee_name varchar(120) not null, primary key (id));
create table thirteenth_month_entries (amount float not null, total_basic float not null, created_at timestamp, id integer, run_id bigint not null, employee_id varchar(40) not null, employee_name varchar(120) not null, primary key (id));
create table thirteenth_month_runs (employee_count integer not null, total_amount float not null, year integer not null, created_at timestamp, id integer, status varchar(12) not null check (status in ('DRAFT','APPROVED','LOCKED')), primary key (id));
create table time_records (absent boolean not null, day_number integer not null, time_in integer not null, time_out integer not null, id integer, cutoff_period varchar(20) not null, holiday_type varchar(24) not null check (holiday_type in ('NONE','REGULAR_HOLIDAY','SPECIAL_OR_REST_DAY')), employee_id varchar(40) not null, primary key (id));
create table users (id integer, role varchar(20) not null check (role in ('ADMIN','HR','EMPLOYEE')), employee_id varchar(40), username varchar(60) not null unique, password_hash varchar(100) not null, primary key (id));
